create type public.promotion_schedule_type as enum ('weekly','date_range');
create table public.promotion_schedule(id uuid primary key default gen_random_uuid(),schedule_type public.promotion_schedule_type not null,weekday smallint check(weekday between 0 and 6),product_id uuid references public.products(id) on delete set null,title text not null check(length(title) between 1 and 100),eyebrow text,subtitle text,promotional_price numeric(10,2) check(promotional_price>=0),start_time time,end_time time,specific_start_at timestamptz,specific_end_at timestamptz,cta_label text not null default 'QUERO AGORA',cta_href text,show_before_start boolean not null default true,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint valid_schedule_shape check((schedule_type='weekly' and weekday is not null and specific_start_at is null and specific_end_at is null) or (schedule_type='date_range' and weekday is null and specific_start_at is not null and specific_end_at is not null and specific_end_at>specific_start_at)),constraint valid_daily_window check(start_time is null or end_time is null or start_time<end_time));
create unique index promotion_weekday_unique on public.promotion_schedule(weekday) where schedule_type='weekly';create index promotion_override_window_idx on public.promotion_schedule(specific_start_at,specific_end_at) where schedule_type='date_range' and is_active;alter table public.promotion_schedule enable row level security;
create policy "public reads currently relevant promotion schedule" on public.promotion_schedule for select to anon,authenticated using(is_active and ((schedule_type='date_range' and now()>=specific_start_at and now()<specific_end_at) or (schedule_type='weekly' and weekday=extract(dow from now() at time zone 'America/Sao_Paulo') and (end_time is null or (now() at time zone 'America/Sao_Paulo')::time<end_time) and (show_before_start or start_time is null or (now() at time zone 'America/Sao_Paulo')::time>=start_time))));
create policy "admins manage promotion schedule" on public.promotion_schedule for all to authenticated using(public.is_admin()) with check(public.is_admin());
insert into public.site_settings(key,value) values('promotion_fallback','{"mode":"show","title":"DÁ UMA OLHADA NO CARDÁPIO.","cta_label":"VER CARDÁPIO","cta_href":"/cardapio"}'::jsonb) on conflict(key) do nothing;
